import { useContext, useState } from 'react';
import { AuthContext } from '../../context/authContext';
import { DarkModeContext } from '../../context/darkModeContext';
import axios from 'axios';
import './share.scss';

const Share = () => {
  const { currentUser } = useContext(AuthContext);
  const { darkMode } = useContext(DarkModeContext);
  const [description, setDescription] = useState('');
  const [file, setFile] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  console.log('Share: Initial render, currentUser=', currentUser ? JSON.stringify(currentUser, null, 2) : 'null');
  console.log('Share: sessionStorage.accessToken=', sessionStorage.getItem('accessToken') || 'null');

  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    if (selectedFile) {
      console.log('Share: File selected:', selectedFile.name);
      setFile(selectedFile);
    } else {
      console.log('Share: No file selected');
      setFile(null);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(null);
    setLoading(true);
    console.log('Share: Form submitted, description=', description, 'file=', file ? file.name : 'null');

    if (!description.trim() && !file) {
      console.error('Share: No description or file provided');
      setError('Please provide a description or select an image.');
      setLoading(false);
      return;
    }

    const token = sessionStorage.getItem('accessToken');
    if (!token) {
      console.error('Share: No accessToken found in sessionStorage');
      setError('Please log in to share a post.');
      setLoading(false);
      return;
    }

    const formData = new FormData();
    if (description.trim()) {
      formData.append('description', description);
    }
    if (file) {
      formData.append('image', file);
    }
    console.log('Share: FormData prepared:', Array.from(formData.entries()));

    try {
      console.log('Share: Posting to http://localhost:5000/api/posts');
      const res = await axios.post('http://localhost:5000/api/posts', formData, {
        headers: {
          Authorization: `Bearer ${token}`,
          // Let axios set Content-Type: multipart/form-data with boundary
        },
      });
      console.log('Share: Post created:', JSON.stringify(res.data, null, 2));
      setDescription('');
      setFile(null);
      setError(null);
      alert('Post shared successfully!');
    } catch (err) {
      console.error('Share: Error creating post:', err.message);
      console.error('Share: Error details:', {
        status: err.response?.status,
        data: JSON.stringify(err.response?.data, null, 2),
      });
      let errorMessage = 'Failed to share post. Please try again.';
      if (err.response?.status === 401) {
        errorMessage = 'Session expired. Please log in again.';
        sessionStorage.removeItem('accessToken');
        sessionStorage.removeItem('user');
      } else if (err.response?.status === 400) {
        errorMessage = err.response.data.message || 'Invalid post data.';
      }
      setError(errorMessage);
    } finally {
      setLoading(false);
      console.log('Share: handleSubmit completed, loading=', false);
    }
  };

  if (!currentUser) {
    console.log('Share: Rendering no currentUser state');
    return <div className={`share ${darkMode ? 'theme-dark' : 'theme-light'}`}>Please log in to share a post.</div>;
  }

  return (
    <div className={`share ${darkMode ? 'theme-dark' : 'theme-light'}`}>
      <h3>Share a Post</h3>
      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <textarea
            placeholder="What's on your mind?"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            className="description-input"
            disabled={loading}
          />
        </div>
        <div className="form-group">
          <input
            type="file"
            accept="image/*"
            onChange={handleFileChange}
            className="file-input"
            disabled={loading}
          />
        </div>
        {error && <p className="error">{error}</p>}
        <button type="submit" className="share-btn" disabled={loading}>
          {loading ? 'Sharing...' : 'Share'}
        </button>
      </form>
    </div>
  );
};

export default Share;
